def plan(tasks):
    warnings = []
    items = {}
    for task in tasks or []:
        if not isinstance(task, dict) or 'id' not in task:
            continue
        items[task['id']] = {
            'deps': [d for d in (task.get('deps') or [])],
            'days': max(1, int(task.get('days', 1))),
            'priority': int(task.get('priority', 99)),
        }
    for tid, info in items.items():
        for dep in info['deps']:
            if dep not in items:
                warnings.append(f'{tid} 依赖的任务 {dep} 不存在')
        info['deps'] = [d for d in info['deps'] if d in items]
    # 拓扑排序：同批次按 (priority, id) 选一个出来
    order = []
    done = set()
    while len(done) < len(items):
        ready = [tid for tid, info in items.items()
                 if tid not in done and all(d in done for d in info['deps'])]
        if not ready:
            if '存在循环依赖，无法排序' not in warnings:
                warnings.append('存在循环依赖，无法排序')
            break
        ready.sort(key=lambda tid: (items[tid]['priority'], tid))
        order.append(ready[0])
        done.add(ready[0])
    # 关键路径：每个任务的最早完成时间 = 自身天数 + 依赖里最大的完成时间
    finish = {}
    for tid in order:
        base = max((finish[d] for d in items[tid]['deps'] if d in finish), default=0)
        finish[tid] = base + items[tid]['days']
    total_days = max(finish.values()) if finish else 0
    return order, total_days, warnings


tasks = [
    {'id': 'T1', 'title': '搭建 FastAPI 骨架', 'deps': [], 'days': 1, 'priority': 1},
    {'id': 'T2', 'title': '设计数据库表', 'deps': [], 'days': 1, 'priority': 2},
    {'id': 'T3', 'title': '实现用户接口', 'deps': ['T1', 'T2'], 'days': 2, 'priority': 1},
    {'id': 'T4', 'title': '接入 DeepSeek', 'deps': ['T3'], 'days': 2, 'priority': 1},
    {'id': 'T5', 'title': '前端页面', 'deps': ['T3'], 'days': 3, 'priority': 2},
]
order, days, warns = plan(tasks)
print(order, days, warns)
